window.kbPageData["views/entry/k-ceb3cf767d4ff48e"] = {"key":"entry/k-ceb3cf767d4ff48e","state":{"route":"entry/k-ceb3cf767d4ff48e"},"node":{"id":"k-ceb3cf767d4ff48e","mode":"k","title":"侵害人身权益造成财产损失的赔偿","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["侵害人身权益造成财产损失的赔偿可按受害人损失或侵权人获利确定"],"qs":["江苏 2023 B类 行测#14"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"侵害他人人身权益并造成财产损失的，赔偿数额按照被侵权人因此受到的损失或者侵权人因此获得的利益确定。损失和获利均难以确定、当事人协商不成并起诉的，由人民法院根据实际情况确定赔偿数额。","review":{"definition":"侵害他人人身权益并造成财产损失的，赔偿数额按照被侵权人因此受到的损失或者侵权人因此获得的利益确定。损失和获利均难以确定、当事人协商不成并起诉的，由人民法院根据实际情况确定赔偿数额。","explanation":"刘某盗用谢某的身份信息虚列工资，导致谢某被认定收入超标并停发特困经济补助。题中可以明确识别的财产损失是被停发的补助，因此A项由刘某赔偿成立。刘某少缴的税款涉及税务追缴，虚列的工资也没有实际用工关系作为支付依据。","references":[],"evidence":"应赔偿谢某被停发的特困经济补助","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 B类 行测#14":{"paper":"江苏 2023 B类 行测","n":14,"mod":"常识判断","src":["22262c34d18cd68fbee4.pdf",3],"asrc":["b08f2713d73015eac675.pdf",6],"card":"66101090aa309c4eebdfef44","links":[{"id":"k-ceb3cf767d4ff48e","role":"直接考查","why":"身份信息被盗用导致补助停发，补助损失可据此向侵权人主张赔偿。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-ceb3cf767d4ff48e":[["江苏 2023 B类 行测#14"]]}};
